package com.aicharacter.v3;import java.util.*;
public final class LifeQualityDevTest {private LifeQualityDevTest(){}public static String runAll(WorldState s){return testOffline(s)+"\n"+testBelief(s)+"\n"+testReunion(s)+"\n"+testDiary(s)+"\n"+testNonVerbal(s);}
 private static String testOffline(WorldState s){s.worldMinutes=18*60;s.body.energy=25;s.body.sleepiness=35;s.environment.weather="CLEAR";HabitState h=s.habits.get("reflect@bench_lake_01");if(h==null){h=new HabitState("reflect@bench_lake_01","evening","reflect","bench_lake_01");s.habits.put(h.key,h);}h.strength=.9;String clear=LifeDecisionEngine.choose(s,System.currentTimeMillis()).intention.id;s.environment.weather="RAIN";s.environment.weatherIntensity=.8;String rain=LifeDecisionEngine.choose(s,System.currentTimeMillis()).intention.id;return"TEST A offline causality: "+(!clear.equals(rain)?"PASS":"FAIL")+" clear="+clear+" rain="+rain;}
 private static String testBelief(WorldState s){BeliefState b=new BeliefState("cat_returns","usually_returns",.35);s.beliefStates.put("cat_returns",b);for(int i=0;i<3;i++){MemoryEntry m=CognitionEngine.process(s,new Experience("return_pattern","The cat returned again.",.1,.65).with("cat").tag("player"));CognitionEngine.reviseFromMemory(s,"cat_returns","usually_returns",1,.6,m);}double hi=b.confidence;MemoryEntry contra=CognitionEngine.process(s,new Experience("long_absence","A long absence contradicted the expected return pattern.",-.2,.9).with("cat").tag("absence"));CognitionEngine.reviseFromMemory(s,"cat_returns","usually_returns",-1,1,contra);boolean refs=true;for(BeliefEvidence e:b.evidence)refs&=!e.sourceMemoryId.isEmpty();return"TEST B belief evidence: "+(refs&&b.confidence<hi?"PASS":"FAIL")+String.format(Locale.US," %.2f -> %.2f refs=%d",hi,b.confidence,b.evidence.size());}
 private static String testReunion(WorldState s){s.reunionContext="test";s.lastAbsenceMinutes=20;s.relationship.attachment=10;s.relationship.irritation=2;s.relationship.hurt=1;HaruMind.Response a=ReunionEngine.process(s,System.currentTimeMillis());String ia=s.currentIntention;s.reunionContext="test";s.lastAbsenceMinutes=3000;s.relationship.attachment=60;s.relationship.irritation=2;s.relationship.hurt=1;HaruMind.Response b=ReunionEngine.process(s,System.currentTimeMillis());String ib=s.currentIntention;s.reunionContext="test";s.lastAbsenceMinutes=3000;s.relationship.irritation=45;s.relationship.hurt=35;HaruMind.Response c=ReunionEngine.process(s,System.currentTimeMillis());String ic=s.currentIntention;return"TEST C reunion cognition: "+((!ia.equals(ib)||!ib.equals(ic))?"PASS":"FAIL")+" intentions="+ia+","+ib+","+ic;}
 private static String testDiary(WorldState s){long now=System.currentTimeMillis();MemoryEntry bench=CognitionEngine.process(s,new Experience("reflection","A calm reflection happened at the bench.",.4,.8).at("lakeside","bench_lake_01").tag("reflect"));MemoryEntry creature=CognitionEngine.process(s,new Experience("creature_encounter","The familiar reedling appeared.",.3,.75).at("lakeside","reedling_01").tag("creature"));DiaryEngine.reflect(s,now+1000);DiaryEntry d=s.diary.get(s.diary.size()-1);boolean grounded=d.sourceMemoryIds.contains(bench.memoryId)||d.sourceMemoryIds.contains(creature.memoryId);return"TEST D diary grounding: "+(grounded?"PASS":"FAIL")+" sourceIds="+d.sourceMemoryIds;}
 private static String testNonVerbal(WorldState s){s.reunionContext="test";s.lastAbsenceMinutes=3000;s.relationship.irritation=70;s.relationship.hurt=60;HaruMind.Response r=ReunionEngine.process(s,System.currentTimeMillis());return"TEST E non-verbal reunion: "+(r.speech.isEmpty()?"PASS":"FAIL")+" action="+s.haruActivity;}}
